import pygame

def step(x, vx, left, right, pressed, dt):
    if vx == 0 and pressed:
        vx = 200
    x += vx * dt
    if x < -6:
        return 320, 0, left, right + 1
    if x > 646:
        return 320, 0, left + 1, right
    return x, vx, left, right
